// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(address burner, uint256 amt) public {
        vm.assume(burner != address(0));

        uint256 amount = bound(amt, 0, type(uint256).max / 2);

        c.mintToken(burner, amount + 1);

        c.mintToken(address(this), amount + 1);

        uint256 before_owner_balance = c.balanceOf(address(this));
        uint256 before_total = c.totalSupply();

        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after_owner_balance = c.balanceOf(address(this));
        uint256 after_total = c.totalSupply();

        assertTrue(!ok || (before_owner_balance - after_owner_balance == before_total - after_total && before_owner_balance >= after_owner_balance));
    }
}
